import{_ as t}from"./chunks/docs-reference-backup-event-dialog.BQnGwD4a.js";import{c as a,Q as s,j as o,m as r}from"./chunks/framework.BqPkuuVc.js";const b=JSON.parse('{"title":"Reporting bugs and sending feedback","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/reporting-bugs-and-feedback.md","filePath":"user/reference/reporting-bugs-and-feedback.md"}'),n={name:"user/reference/reporting-bugs-and-feedback.md"};function i(h,e,d,l,u,g){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="reporting-bugs-and-sending-feedback" tabindex="-1">Reporting bugs and sending feedback <a class="header-anchor" href="#reporting-bugs-and-sending-feedback" aria-label="Permalink to &quot;Reporting bugs and sending feedback&quot;">​</a></h1><p><strong>Audience:</strong> Anyone using meshO Manager who has found a problem, has a question, or has an idea.</p><p>How to tell us about a bug, ask a question, suggest a feature, or point out something wrong in these docs. There are two ways in: <strong>email</strong> and <strong>GitHub Issues</strong>.</p><h2 id="which-one-to-use" tabindex="-1">Which one to use <a class="header-anchor" href="#which-one-to-use" aria-label="Permalink to &quot;Which one to use&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to…</th><th>Use</th></tr></thead><tbody><tr><td>Get help with a problem, especially one at an event</td><td><a href="#email">Email</a></td></tr><tr><td>Send anything that includes an event backup or competitors&#39; details</td><td><a href="#email">Email</a></td></tr><tr><td>Ask a question</td><td><a href="#email">Email</a></td></tr><tr><td>Report a bug you can describe without private data</td><td>Either — <a href="#github-issues">GitHub Issues</a> lets other users see it and add to it</td></tr><tr><td>Suggest a feature or an improvement</td><td>Either — <a href="#github-issues">GitHub Issues</a> lets other users vote for it</td></tr><tr><td>Point out something wrong or missing in these docs</td><td>Either</td></tr></tbody></table><p>If you&#39;re not sure, email. Nothing is lost by choosing the &quot;wrong&quot; one.</p><h2 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h2><p>Write to <strong><a href="mailto:help@mesho.live" target="_blank" rel="noreferrer">help@mesho.live</a></strong>.</p><p>Email is private, so it&#39;s the right place for anything that includes an event backup, a log file, or competitors&#39; names and details. It suits questions and urgent problems too.</p><h2 id="github-issues" tabindex="-1">GitHub Issues <a class="header-anchor" href="#github-issues" aria-label="Permalink to &quot;GitHub Issues&quot;">​</a></h2><p>Open an issue at <strong><a href="https://github.com/mesho-live/manager-releases/issues" target="_blank" rel="noreferrer">github.com/mesho-live/manager-releases/issues</a></strong>. You need a free GitHub account.</p><p>Before opening a new one, search the existing issues: if somebody has already reported the same bug or asked for the same feature, add a comment or a 👍 to theirs. That tells us how many people it affects.</p><div class="danger custom-block"><p class="custom-block-title">Issues are public</p><p>Anyone on the internet can read an issue and anything attached to it. <strong>Never attach an event backup, a log file, or a screenshot showing competitors&#39; details to an issue.</strong> An event backup holds competitors&#39; personal details and the event&#39;s <a href="./../running-the-event/publishing-live-results">liveresultat</a> upload password. If an issue needs any of these, say so in the issue and email them to <a href="mailto:help@mesho.live" target="_blank" rel="noreferrer">help@mesho.live</a>, mentioning the issue number.</p></div><h2 id="reporting-a-bug" tabindex="-1">Reporting a bug <a class="header-anchor" href="#reporting-a-bug" aria-label="Permalink to &quot;Reporting a bug&quot;">​</a></h2><p>The more of this you can include, the faster it can be found and fixed:</p><ol><li><p><strong>What you did, what you expected, and what happened instead.</strong> A step-by-step list is best: &quot;Opened the competitor, changed the class to M21E, pressed Save — the status went back to DNS.&quot;</p></li><li><p><strong>Roughly when it happened.</strong> The time helps find it in the log.</p></li><li><p><strong>The version</strong>, from <strong>About</strong> in the tray or menu bar.</p></li><li><p><strong>Your computer</strong>: Windows, Mac or Linux, and which browser if the problem is in a page.</p></li><li><p><strong>A screenshot</strong>, if the problem is something you can see.</p></li><li><p><strong>That day&#39;s log file</strong>, by email. <a href="./troubleshooting#where-the-logs-are">Troubleshooting</a> says where to find it.</p></li><li><p><strong>A backup of the event</strong>, by email, if the problem is about an event: <strong>Backup event → Download</strong> on its card. It includes the event&#39;s <a href="./audit-trail">audit trail</a>, card downloads and radio data, which is usually what&#39;s needed to see what happened. See <a href="./backup-and-restore">Backup and restore</a>.</p><p><img src="'+t+'" alt="The Backup event dialog: Save on server or Download"></p></li></ol><p>If you can make it happen again, say so and how; if it happened once and you can&#39;t, say that too. Both are worth reporting.</p><h2 id="suggesting-a-feature" tabindex="-1">Suggesting a feature <a class="header-anchor" href="#suggesting-a-feature" aria-label="Permalink to &quot;Suggesting a feature&quot;">​</a></h2><p>Tell us <strong>what you&#39;re trying to do and why</strong>, not only the feature you have in mind: &quot;At our <a href="./../event-setup/multi-stage-events">carnivals</a> the start team needs to see who is late for their start, so we can call them&quot; says more than &quot;add a late-starters list&quot;, and may have an answer that already exists. Say how often it comes up and what you do today instead.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./troubleshooting">Troubleshooting</a></li><li><a href="./../running-the-event/resolving-issues">Resolving issues on the day</a></li><li><a href="./backup-and-restore">Backup and restore</a></li></ul>',21)])])}const m=a(n,[["render",i]]);export{b as __pageData,m as default};
